import type { Person } from './person-model';
import type { Request } from './request-model';
import type { Workspace } from './workspace-model';

export interface RequestHistory {
  /**
   * @displayName Request History ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Change Type
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  changeType: string;
  /**
   * @displayName Actor Person ID
   * @validationRule Required for create/update operations
   */
  actorPersonID: Pick<Person, 'id' | 'displayName'>;
  /**
   * @displayName Changed At
   * @validationRule Required for create/update operations
   */
  changedAt: string;
  /**
   * @displayName Field Name
   * @validationRule Required for create/update operations
   */
  fieldName: string;
  /**
   * @displayName New Value
   */
  newValue?: string;
  /**
   * @displayName Old Value
   */
  oldValue?: string;
  /**
   * @displayName Reason
   */
  reason?: string;
  /**
   * @displayName Request ID
   * @validationRule Required for create/update operations
   */
  requestID: Pick<Request, 'id' | 'requestNumber'>;
  /**
   * @displayName Source
   * @validationRule Required for create/update operations
   */
  source: string;
  /**
   * @displayName Workspace ID
   * @validationRule Required for create/update operations
   */
  workspaceID: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _RequestHistory = 'RequestHistory' as const;